document.getElementById('operationTimes').innerHTML='<div class="customer-insight"><span class="muted">Request → review</span><b>'+formatDuration(ops.averageReviewMinutes)+'</b><small class="muted">Average</small></div><div class="customer-insight"><span class="muted">Review → quote</span><b>'+formatDuration(ops.averageQuoteMinutes)+'</b><small class="muted">Average</small></div><div class="customer-insight"><span class="muted">Payment request → paid</span><b>'+formatDuration(ops.averagePaymentMinutes)+'</b><small class="muted">Average</small></div><div class="customer-insight"><span class="muted">Paid → ready/shipped</span><b>'+formatDuration(ops.averageFulfilmentMinutes)+'</b><small class="muted">Average</small></div>';
