function stocktakeScopeReferenceOptions(type){var items=[];if(type==='STOREFRONT_NODE'){items=storefrontNodes.filter(function(n){return n.publicationStatus!=='ARCHIVED'}).map(function(n){return{id:n.id,name:storefrontPathLabel(n.id)}})}else if(type==='BRAND_RANGE'){items=categoryManagerCategories.filter(function(x){return x.active!==false&&x.categoryType==='BRAND_RANGE'}).map(function(x){return{id:x.id,name:x.name}})}else if(type==='CATEGORY'){items=categoryManagerCategories.filter(function(x){return x.active!==false&&x.categoryType!=='BRAND_RANGE'}).map(function(x){return{id:x.id,name:x.name}})}return items.sort(function(a,b){return String(a.name).localeCompare(String(b.name))})}
function stocktakeLauncherPayload(){var type=(document.getElementById('stocktakeScopeType')||{}).value||'ENTIRE_SHOP',location=(document.getElementById('stockLocation')&&document.getElementById('stockLocation').value)||'loc_ambleside',payload={locationId:location,scopeType:type};if(type==='STOREFRONT_NODE'||type==='BRAND_RANGE'||type==='CATEGORY'){payload.scopeRefId=(document.getElementById('stocktakeScopeRef')||{}).value||''}else if(type==='CUSTOM'){payload.customVariantIds=Array.from(document.querySelectorAll('#stocktakeCustomList input:checked')).map(function(x){return x.value})}return payload}
function stocktakeResumeHtml(){if(!stocktakeSessions.length)return '<div class="muted" style="font-size:11px">No unfinished stocktakes.</div>';return '<div class="stocktake-resume-list">'+stocktakeSessions.map(function(s){var done=Number(s.countedItems||0)+Number(s.skippedItems||0),pct=Math.round((done/Math.max(1,Number(s.totalItems||0)))*100);return '<div class="stocktake-resume-row"><div><strong>'+esc(s.scopeLabel)+'</strong><small>'+done+' of '+esc(s.totalItems)+' reviewed · '+pct+'%'+(Number(s.conflictItems||0)?' · '+s.conflictItems+' need review':'')+' · '+esc(labelStatus(s.status))+'</small></div><div class="stocktake-resume-actions"><button class="btn secondary" data-stocktake-resume="'+esc(s.id)+'">Continue</button><button class="btn secondary" data-stocktake-cancel="'+esc(s.id)+'">Cancel</button></div></div>'}).join('')+'</div>'}
function stocktakeCustomListHtml(){return inventoryCache.map(function(item){return '<label class="stocktake-custom-item" data-stocktake-custom-label><input type="checkbox" value="'+esc(item.variantId)+'"><span><strong>'+esc(item.title)+'</strong><small>'+esc(item.sku||'No SKU')+'</small></span></label>'}).join('')}
async function openStocktakeLauncher(){try{if(!stockLoaded)await loadInventory();var location=(document.getElementById('stockLocation')&&document.getElementById('stockLocation').value)||'loc_ambleside',results=await Promise.all([api('/admin/api/storefront-structure?includeArchived=1'),api('/admin/api/categories?includeArchived=1'),api('/admin/api/stocktakes?location='+encodeURIComponent(location))]);storefrontNodes=results[0].nodes||[];categoryManagerCategories=results[1].categories||[];stocktakeSessions=results[2].sessions||[];openProductSheet('<div class="catalog-sheet-panel stocktake-launcher"><div class="sheet-head"><div><div class="eyebrow">Stocktake 2.0</div><h3>Start or continue a stocktake</h3></div><button class="sheet-close" data-close-product-sheet>×</button></div><div class="editor-intro">Choose only what you want to count. Progress is saved after every Count or Skip, so you can close this screen and continue later.</div><section class="product-section"><h3>Continue unfinished</h3><div id="stocktakeResumeList">'+stocktakeResumeHtml()+'</div></section><section class="product-section"><h3>Start new</h3><div class="stocktake-scope-grid"><div class="editor-field"><label>Count</label><select class="field" id="stocktakeScopeType"><option value="ENTIRE_SHOP">Entire shop</option><option value="STOREFRONT_NODE">Website section</option><option value="BRAND_RANGE">Brand / Range</option><option value="CATEGORY">Product category / collection</option><option value="CUSTOM">Custom products</option></select></div><div class="editor-field hidden" id="stocktakeScopeRefWrap"><label id="stocktakeScopeRefLabel">Choose</label><select class="field" id="stocktakeScopeRef"></select></div></div><div class="hidden" id="stocktakeCustomWrap" style="margin-top:10px"><label>Choose products</label><input class="field" id="stocktakeCustomSearch" placeholder="Search product or SKU…" autocomplete="off"><div class="stocktake-custom-list" id="stocktakeCustomList">'+stocktakeCustomListHtml()+'</div></div><div class="stocktake-preview" id="stocktakePreview"><strong>Checking scope…</strong><small>We will show the product count before you start.</small></div></section><div class="editor-actions"><button class="btn secondary" data-close-product-sheet>Close</button><button class="btn" id="stocktakeStart" disabled>Start stocktake</button></div></div>');document.querySelectorAll('[data-close-product-sheet]').forEach(function(b){b.onclick=closeCatalogSheet});wireStocktakeLauncher();await previewStocktakeLauncher()}catch(e){showToast(e.message,true)}}
function refreshStocktakeScopeControls(){var type=document.getElementById('stocktakeScopeType').value,refWrap=document.getElementById('stocktakeScopeRefWrap'),customWrap=document.getElementById('stocktakeCustomWrap'),ref=document.getElementById('stocktakeScopeRef'),label=document.getElementById('stocktakeScopeRefLabel'),needsRef=['STOREFRONT_NODE','BRAND_RANGE','CATEGORY'].includes(type);refWrap.classList.toggle('hidden',!needsRef);customWrap.classList.toggle('hidden',type!=='CUSTOM');if(needsRef){var labels={STOREFRONT_NODE:'Website section',BRAND_RANGE:'Brand / Range',CATEGORY:'Category / collection'},items=stocktakeScopeReferenceOptions(type);label.textContent=labels[type];ref.innerHTML='<option value="">Choose…</option>'+items.map(function(x){return '<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>'}).join('')}previewStocktakeLauncher()}
function filterStocktakeCustom(){var q=(document.getElementById('stocktakeCustomSearch').value||'').trim().toLowerCase();document.querySelectorAll('[data-stocktake-custom-label]').forEach(function(row){row.classList.toggle('hidden',!!q&&!row.textContent.toLowerCase().includes(q))})}
function wireStocktakeLauncher(){var type=document.getElementById('stocktakeScopeType'),ref=document.getElementById('stocktakeScopeRef'),search=document.getElementById('stocktakeCustomSearch'),custom=document.getElementById('stocktakeCustomList'),start=document.getElementById('stocktakeStart');type.onchange=refreshStocktakeScopeControls;ref.onchange=previewStocktakeLauncher;if(search)search.oninput=filterStocktakeCustom;if(custom)custom.onchange=previewStocktakeLauncher;if(start)start.onclick=createPersistentStocktake;document.querySelectorAll('[data-stocktake-resume]').forEach(function(b){b.onclick=function(){loadPersistentStocktake(b.getAttribute('data-stocktake-resume'))}});document.querySelectorAll('[data-stocktake-cancel]').forEach(function(b){b.onclick=function(){cancelPersistentStocktake(b.getAttribute('data-stocktake-cancel'))}})}
async function previewStocktakeLauncher(){var box=document.getElementById('stocktakePreview'),start=document.getElementById('stocktakeStart');if(!box||!start)return;start.disabled=true;var payload=stocktakeLauncherPayload(),type=payload.scopeType;if((['STOREFRONT_NODE','BRAND_RANGE','CATEGORY'].includes(type)&&!payload.scopeRefId)||(type==='CUSTOM'&&!(payload.customVariantIds||[]).length)){box.innerHTML='<strong>Choose a scope.</strong><small>Select what you want to count.</small>';return}box.innerHTML='<strong>Checking scope…</strong><small>Counting products in this selection.</small>';try{var d=await api('/admin/api/stocktakes/preview',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});box.innerHTML='<strong>'+esc(d.scopeLabel)+' · '+esc(d.totalItems)+' '+(Number(d.totalItems)===1?'product':'products')+'</strong><small>This is the exact stocktake scope that will be saved.</small>';start.disabled=Number(d.totalItems)<1}catch(e){box.innerHTML='<strong>Cannot start this scope.</strong><small>'+esc(e.message)+'</small>'}}
async function createPersistentStocktake(){var button=document.getElementById('stocktakeStart');if(!button||button.disabled)return;button.disabled=true;try{var d=await api('/admin/api/stocktakes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(stocktakeLauncherPayload())});stocktakeState={session:d.session,items:d.items||[],index:0};openPersistentStocktakeSheet()}catch(e){showToast(e.message,true);button.disabled=false}}
async function loadPersistentStocktake(id){try{var d=await api('/admin/api/stocktakes/'+encodeURIComponent(id));stocktakeState={session:d.session,items:d.items||[],index:0};var items=stocktakeState.items;if(d.session.status==='REVIEW'){var conflict=items.findIndex(function(x){return x.itemStatus==='CONFLICT'});stocktakeState.index=conflict>=0?conflict:0}else{var pos=Math.max(0,Number(d.session.currentPosition||0));if(pos>=items.length){renderPersistentStocktakeReview();return}stocktakeState.index=pos}openPersistentStocktakeSheet()}catch(e){showToast(e.message,true)}}
