function openPersistentStocktakeSheet(){if(!stocktakeState||!stocktakeState.items.length){showToast('This stocktake has no products.',true);return}openProductSheet('<div class="catalog-sheet-panel stocktake-count-shell"><div class="sheet-head"><div><div class="eyebrow" id="stocktakeProgressLabel">Stocktake</div><h3>Physical count</h3></div><button class="sheet-close" data-close-product-sheet>×</button></div><div><span class="stocktake-scope-pill" id="stocktakeScopePill"></span></div><div class="stocktake-progress"><span id="stocktakeProgressBar"></span></div><div class="stocktake-count-body"><div class="stocktake-conflict hidden" id="stocktakeConflict"></div><div class="stocktake-product"><div id="stocktakeImage"></div><div><div class="product-row-title" id="stocktakeTitle"></div><div class="product-row-meta" id="stocktakeSku"></div><div class="stocktake-system"><span id="stocktakeSystem"></span><span id="stocktakeAvailable"></span></div></div></div><div class="editor-field"><label>Physical quantity</label><input class="field stocktake-count" id="stocktakeQty" type="number" inputmode="numeric" enterkeyhint="next" min="0" step="1" autocomplete="off"></div></div><div class="editor-actions"><button class="btn secondary" id="stocktakePrev">Previous</button><button class="btn secondary" id="stocktakeSkip">Skip</button><button class="btn" id="stocktakeNext">Save &amp; next</button></div></div>');document.querySelectorAll('[data-close-product-sheet]').forEach(function(b){b.onclick=closeCatalogSheet});var prev=document.getElementById('stocktakePrev'),skip=document.getElementById('stocktakeSkip'),next=document.getElementById('stocktakeNext'),input=document.getElementById('stocktakeQty');[prev,skip,next].forEach(function(b){if(b)b.onpointerdown=function(e){e.preventDefault()}});prev.onclick=navigatePersistentStocktakePrevious;skip.onclick=function(){savePersistentStocktakeItem('SKIP')};next.onclick=function(){savePersistentStocktakeItem('COUNT')};input.onkeydown=function(e){if(e.key==='Enter'){e.preventDefault();savePersistentStocktakeItem('COUNT')}};renderPersistentStocktakeItem(true)}
function currentStocktakeItem(){return stocktakeState&&stocktakeState.items[stocktakeState.index]}
function renderPersistentStocktakeItem(focus){if(!stocktakeState)return;var s=stocktakeState.session,item=currentStocktakeItem();if(!item){renderPersistentStocktakeReview();return}var total=stocktakeState.items.length,index=stocktakeState.index,pct=Math.round((index/Math.max(1,total))*100),conflict=item.itemStatus==='CONFLICT',onHand=conflict?item.currentOnHand:item.systemOnHandSnapshot,available=conflict?item.currentAvailable:item.availableSnapshot;document.getElementById('stocktakeProgressLabel').textContent='Stocktake · '+(index+1)+' of '+total;document.getElementById('stocktakeScopePill').textContent=s.scopeLabel;document.getElementById('stocktakeProgressBar').style.width=pct+'%';document.getElementById('stocktakeTitle').textContent=item.title;document.getElementById('stocktakeSku').textContent=item.sku||'No SKU';document.getElementById('stocktakeSystem').textContent='System: '+(item.currentTracked?stockNumber(onHand):'Untracked');document.getElementById('stocktakeAvailable').textContent='Available: '+(item.currentTracked?stockNumber(available):'—');document.getElementById('stocktakeImage').innerHTML=item.thumbnailUrl?'<img src="'+esc(item.thumbnailUrl)+'" alt="">':'<div class="stocktake-placeholder">◇</div>';var conflictBox=document.getElementById('stocktakeConflict');conflictBox.classList.toggle('hidden',!conflict);conflictBox.innerHTML=conflict?'<strong>Stock changed while you were counting.</strong> Enter a fresh physical count. The current system value is shown below.':'';var input=document.getElementById('stocktakeQty');input.value=item.countedOnHand==null?'':String(item.countedOnHand);document.getElementById('stocktakePrev').disabled=index===0;document.getElementById('stocktakeSkip').textContent=index===total-1?'Skip & review':'Skip';document.getElementById('stocktakeNext').textContent=index===total-1?'Save & review':'Save & next';if(focus)requestAnimationFrame(function(){try{input.focus({preventScroll:true});input.select()}catch(e){input.focus()}})}
function navigatePersistentStocktakePrevious(){if(stocktakeBusy||!stocktakeState||stocktakeState.index===0)return;var input=document.getElementById('stocktakeQty'),item=currentStocktakeItem(),raw=input.value.trim(),saved=item.countedOnHand==null?'':String(item.countedOnHand);if(raw!==saved&&raw!==''){savePersistentStocktakeItem('COUNT',stocktakeState.index-1);return}stocktakeState.index--;renderPersistentStocktakeItem(true)}
async function savePersistentStocktakeItem(action,targetIndex){if(stocktakeBusy||!stocktakeState)return;var item=currentStocktakeItem(),input=document.getElementById('stocktakeQty'),raw=input.value.trim();if(action==='COUNT'&&(raw===''||!Number.isInteger(Number(raw))||Number(raw)<0)){showToast('Enter a physical quantity or use Skip.',true);renderPersistentStocktakeItem(true);return}stocktakeBusy=true;try{input.focus({preventScroll:true});var d=await api('/admin/api/stocktakes/'+encodeURIComponent(stocktakeState.session.id)+'/items/'+encodeURIComponent(item.variantId),{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({expectedItemVersion:item.version,action:action,countedOnHand:action==='COUNT'?Number(raw):null})});stocktakeState.session=d.session;stocktakeState.items=d.items||[];if(typeof targetIndex==='number'){stocktakeState.index=Math.max(0,Math.min(stocktakeState.items.length-1,targetIndex))}else if(stocktakeState.index<stocktakeState.items.length-1){stocktakeState.index++}else{stocktakeBusy=false;renderPersistentStocktakeReview();return}renderPersistentStocktakeItem(true)}catch(e){showToast(e.message,true);try{var fresh=await api('/admin/api/stocktakes/'+encodeURIComponent(stocktakeState.session.id));stocktakeState.session=fresh.session;stocktakeState.items=fresh.items||stocktakeState.items;var same=stocktakeState.items.findIndex(function(x){return x.variantId===item.variantId});if(same>=0)stocktakeState.index=same;renderPersistentStocktakeItem(true)}catch(ignore){}}finally{stocktakeBusy=false}}
function renderPersistentStocktakeReview(){if(!stocktakeState)return;var s=stocktakeState.session,items=stocktakeState.items,counted=items.filter(function(x){return x.itemStatus==='COUNTED'||x.itemStatus==='CONFLICT'}),skipped=items.filter(function(x){return x.itemStatus==='SKIPPED'}),rows=counted.map(function(item){return '<div class="stocktake-review-row"><div><strong>'+esc(item.title)+'</strong><small>'+esc(item.itemStatus==='CONFLICT'?'Needs fresh review':item.sku||'No SKU')+'</small></div><strong>'+esc(item.countedOnHand==null?'—':item.countedOnHand)+'</strong></div>'}).join('');openProductSheet('<div class="catalog-sheet-panel stocktake-count-shell"><div class="sheet-head"><div><div class="eyebrow">Stocktake review · '+esc(s.scopeLabel)+'</div><h3>'+counted.length+' counts ready</h3></div><button class="sheet-close" data-close-product-sheet>×</button></div><div class="editor-intro">Counts are saved already, but inventory is not changed until you finish. If stock changed during the count, that product goes to review instead of being overwritten.</div><div class="stock-result-grid">'+metricCard('Counted',String(counted.length),'Ready to apply')+metricCard('Skipped',String(skipped.length),'Not changed')+metricCard('Total',String(items.length),s.scopeLabel)+'</div><div class="stocktake-review-list">'+(rows||'<div class="empty">No counts entered yet.</div>')+'</div><div class="editor-actions"><button class="btn secondary" id="stocktakeBackToCount">Back to count</button><button class="btn" id="stocktakeFinalize" '+(!counted.length?'disabled':'')+'>Finish stocktake</button></div></div>');document.querySelectorAll('[data-close-product-sheet]').forEach(function(b){b.onclick=closeCatalogSheet});document.getElementById('stocktakeBackToCount').onclick=function(){stocktakeState.index=Math.max(0,Math.min(stocktakeState.items.length-1,Number(stocktakeState.session.currentPosition||0)));openPersistentStocktakeSheet()};document.getElementById('stocktakeFinalize').onclick=finalizePersistentStocktake}
async function finalizePersistentStocktake(){if(stocktakeBusy||!stocktakeState)return;stocktakeBusy=true;var button=document.getElementById('stocktakeFinalize');if(button){button.disabled=true;button.textContent='Finishing…'}try{var d=await api('/admin/api/stocktakes/'+encodeURIComponent(stocktakeState.session.id)+'/finalize',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});stocktakeState.session=d.session;stocktakeState.items=d.items||[];var result=d.result||{},conflicts=result.conflicts||[],success=(result.success||[]).length,unchanged=(result.unchanged||[]).length;if(conflicts.length){openProductSheet('<div class="catalog-sheet-panel stocktake-count-shell"><div class="sheet-head"><div><div class="eyebrow">Stocktake needs review</div><h3>'+conflicts.length+' '+(conflicts.length===1?'item':'items')+' changed</h3></div><button class="sheet-close" data-close-product-sheet>×</button></div><div class="editor-intro">These products changed while you were counting, so the system did not overwrite them. Recount only those items against the current stock values.</div><div class="stock-result-grid">'+metricCard('Updated',String(success),'Applied safely')+metricCard('No change',String(unchanged),'Already matched')+metricCard('Review',String(conflicts.length),'Recount needed')+'</div><div class="editor-actions"><button class="btn secondary" data-close-product-sheet>Close for now</button><button class="btn" id="stocktakeReviewConflicts">Review '+conflicts.length+' items</button></div></div>');document.querySelectorAll('[data-close-product-sheet]').forEach(function(b){b.onclick=closeCatalogSheet});document.getElementById('stocktakeReviewConflicts').onclick=function(){var idx=stocktakeState.items.findIndex(function(x){return x.itemStatus==='CONFLICT'});stocktakeState.index=idx>=0?idx:0;openPersistentStocktakeSheet()}}else{openProductSheet('<div class="catalog-sheet-panel stocktake-count-shell"><div class="sheet-head"><div><div class="eyebrow">Stocktake completed</div><h3>'+esc(stocktakeState.session.scopeLabel)+'</h3></div><button class="sheet-close" data-close-product-sheet>×</button></div><div class="stock-result-grid">'+metricCard('Updated',String(success),'Stock changed')+metricCard('No change',String(unchanged),'Already matched')+metricCard('Skipped',String(stocktakeState.session.skippedItems||0),'Not changed')+'</div><div class="stock-ok"><strong>Stocktake completed.</strong> All saved counts were applied safely.</div><div class="editor-actions"><button class="btn" id="stocktakeDone">Done</button></div></div>');document.getElementById('stocktakeDone').onclick=function(){stocktakeState=null;closeCatalogSheet();stockLoaded=false;loadInventory()}}}catch(e){showToast(e.message,true);if(button){button.disabled=false;button.textContent='Finish stocktake'}}finally{stocktakeBusy=false}}
function productStatusLabel(p){if(p.publicationStatus==='ARCHIVED')return '<span class="product-state out">Archived</span>';if(p.sellStatus==='OUT_OF_STOCK')return '<span class="product-state out">Out of stock</span>';if(p.sellStatus==='ARRIVING_SOON')return '<span class="product-state arriving">Arriving soon</span>';if(!p.onlineOrderingEnabled)return '<span class="product-state untracked">In store only</span>';if(p.inventory&&p.inventory.tracked&&p.inventory.out)return '<span class="product-state out">Stock out</span>';if(p.inventory&&p.inventory.tracked&&p.inventory.low)return '<span class="product-state arriving">Low stock</span>';if(p.inventory&&!p.inventory.tracked)return '';return '<span class="product-state available">Available</span>'}
function qualityHtml(flags){var f=flags||[];if(!f.length)return '<span class="quality-chip good">Catalogue complete</span>';var labels={MISSING_PRICE:'Missing price',MISSING_IMAGE:'Missing image',SOURCE_WARNING:'Data warning',DRAFT_CHANGES:'Draft changes'};return f.map(function(x){return '<span class="quality-chip">'+esc(labels[x]||x)+'</span>'}).join('')}
