function renderHomepageFeatured(){var root=document.getElementById('homepageFeaturedProducts');if(!root)return;root.innerHTML=homepageFeaturedIds.length?homepageFeaturedIds.map(function(id,index){var p=homepageProductData(id),img=p.primaryImageUrl?'<img src="'+esc(p.primaryImageUrl)+'" alt="">':'<div class="homepage-product-ph">◇</div>';return '<div class="homepage-product-row" draggable="true" data-homepage-featured="'+esc(id)+'">'+img+'<div><strong>'+esc(p.title||'Product')+'</strong><small>'+esc((p.sku?'SKU '+p.sku+' · ':'')+(p.publicationStatus&&p.publicationStatus!=='ACTIVE'?'Draft product':'Published product'))+'</small></div><div class="homepage-product-actions"><button class="btn secondary" data-homepage-move="-1" data-product-id="'+esc(id)+'" '+(index===0?'disabled':'')+'>↑</button><button class="btn secondary" data-homepage-move="1" data-product-id="'+esc(id)+'" '+(index===homepageFeaturedIds.length-1?'disabled':'')+'>↓</button><button class="btn danger" data-homepage-remove="'+esc(id)+'">×</button></div></div>'}).join(''):'<div class="empty">No Featured products selected yet.</div>';root.querySelectorAll('[data-homepage-move]').forEach(function(b){b.onclick=function(){moveHomepageFeatured(b.getAttribute('data-product-id'),Number(b.getAttribute('data-homepage-move')))}});root.querySelectorAll('[data-homepage-remove]').forEach(function(b){b.onclick=function(){removeHomepageFeatured(b.getAttribute('data-homepage-remove'))}});var dragId='';root.querySelectorAll('[data-homepage-featured]').forEach(function(row){row.ondragstart=function(){dragId=row.getAttribute('data-homepage-featured')||''};row.ondragover=function(e){e.preventDefault()};row.ondrop=function(e){e.preventDefault();var target=row.getAttribute('data-homepage-featured')||'',from=homepageFeaturedIds.indexOf(dragId),to=homepageFeaturedIds.indexOf(target);if(from<0||to<0||from===to)return;homepageFeaturedIds.splice(from,1);homepageFeaturedIds.splice(to,0,dragId);renderHomepageFeatured()}})}
function moveHomepageFeatured(id,direction){var index=homepageFeaturedIds.indexOf(id),target=index+direction;if(index<0||target<0||target>=homepageFeaturedIds.length)return;var tmp=homepageFeaturedIds[index];homepageFeaturedIds[index]=homepageFeaturedIds[target];homepageFeaturedIds[target]=tmp;renderHomepageFeatured()}
function removeHomepageFeatured(id){homepageFeaturedIds=homepageFeaturedIds.filter(function(x){return x!==id});renderHomepageFeatured()}
function addHomepageFeatured(id){if(!id||homepageFeaturedIds.includes(id))return;if(homepageFeaturedIds.length>=20){showToast('Choose no more than 20 Featured products.',true);return}homepageFeaturedIds.push(id);renderHomepageFeatured();renderHomepageProductResults([])}
function renderHomepageProductResults(rows){var root=document.getElementById('homepageProductResults');if(!root)return;var list=(rows||[]).filter(function(p){return p.publicationStatus!=='ARCHIVED'&&!homepageFeaturedIds.includes(p.id)}).slice(0,12);root.innerHTML=list.map(function(p){homepageProductOptions.set(p.id,p);return '<button class="catalog-option" type="button" data-homepage-add="'+esc(p.id)+'"><span><strong>'+esc(p.title)+'</strong><small>'+esc((p.sku?'SKU '+p.sku+' · ':'')+(p.publicationStatus==='ACTIVE'?'Published':'Draft'))+'</small></span><span>+ Add</span></button>'}).join('');root.querySelectorAll('[data-homepage-add]').forEach(function(b){b.onclick=function(){addHomepageFeatured(b.getAttribute('data-homepage-add'))}})}
async function searchHomepageProducts(){var field=document.getElementById('homepageProductSearch'),q=(field&&field.value||'').trim();if(!q){renderHomepageProductResults([]);return}try{var d=await api('/admin/api/products?limit=50&q='+encodeURIComponent(q)+'&sort=updated');renderHomepageProductResults(d.products||[])}catch(e){showToast(e.message,true)}}
function homepageModuleLabel(key){return{HERO:'Hero & quick links',COLLECTIONS:'Shop by collection',PRODUCT_RAIL:'Product strip',LOCAL_FAVOURITES:'Local favourites',VISIT_SHOP:'Visit / shop story'}[key]||key}
function homepageModuleDescription(key){return{HERO:'Main image, introduction and quick links.',COLLECTIONS:'Core gift collection cards.',PRODUCT_RAIL:'The products configured on this page.',LOCAL_FAVOURITES:"Ice cream, Romney's and Hawkshead Relish.",VISIT_SHOP:'The final shop story and browse-all prompt.'}[key]||''}
function homepageModulesNormalized(){var defaults=['HERO','PRODUCT_RAIL','COLLECTIONS','LOCAL_FAVOURITES','VISIT_SHOP'];var rows=Array.isArray(homepageConfig&&homepageConfig.modules)?homepageConfig.modules.slice():[];var byKey=new Map(rows.map(function(row){return[row.key,row]})),pinned=['HERO','PRODUCT_RAIL','COLLECTIONS'];var base=defaults.map(function(key,index){var row=byKey.get(key);return{key:key,enabled:row?row.enabled!==false:true,position:row&&Number.isFinite(Number(row.position))?Number(row.position):(index+1)*10}}),tail=base.filter(function(row){return!pinned.includes(row.key)}).sort(function(a,b){return a.position-b.position}),ordered=pinned.map(function(key){return base.find(function(row){return row.key===key})}).concat(tail);ordered.forEach(function(row,index){row.position=(index+1)*10});return ordered}
function renderHomepageModules(){var root=document.getElementById('homepageModules');if(!root||!homepageConfig)return;var rows=homepageModulesNormalized(),pinned=new Set(['HERO','PRODUCT_RAIL','COLLECTIONS']);homepageConfig.modules=rows;root.innerHTML=rows.map(function(row,index){var locked=pinned.has(row.key);return '<div class="homepage-module-row" data-homepage-module="'+esc(row.key)+'"><label class="homepage-module-copy"><input type="checkbox" data-homepage-module-enabled="'+esc(row.key)+'" '+(row.enabled?'checked':'')+'><span><strong>'+esc(homepageModuleLabel(row.key))+'</strong><small>'+esc(homepageModuleDescription(row.key))+(locked?' Fixed position':'')+'</small></span></label><div class="homepage-module-actions">'+(locked?'':'<button class="btn secondary" type="button" data-homepage-module-move="-1" data-homepage-module-key="'+esc(row.key)+'" '+(index===0?'disabled':'')+'>↑</button><button class="btn secondary" type="button" data-homepage-module-move="1" data-homepage-module-key="'+esc(row.key)+'" '+(index===rows.length-1?'disabled':'')+'>↓</button>')+'</div></div>'}).join('');root.querySelectorAll('[data-homepage-module-enabled]').forEach(function(input){input.onchange=function(){var key=input.getAttribute('data-homepage-module-enabled'),row=homepageConfig.modules.find(function(x){return x.key===key});if(row)row.enabled=input.checked}});root.querySelectorAll('[data-homepage-module-move]').forEach(function(button){button.onclick=function(){var key=button.getAttribute('data-homepage-module-key'),direction=Number(button.getAttribute('data-homepage-module-move')||0),rows=homepageModulesNormalized(),index=rows.findIndex(function(x){return x.key===key}),target=index+direction;if(index<3||target<3||target>=rows.length)return;var tmp=rows[index];rows[index]=rows[target];rows[target]=tmp;rows.forEach(function(row,i){row.position=(i+1)*10});homepageConfig.modules=rows;renderHomepageModules()}})}
function homepageModulesPayload(){return homepageModulesNormalized().map(function(row){return{key:row.key,enabled:row.enabled!==false}})}
function renderHomepage(){clearPublicationVerification('homepage');if(!homepageConfig)return;var c=homepageConfig,status=document.getElementById('homepageStatus');if(status)status.innerHTML=(c.hasDraft?'<span class="structure-badge draft">Draft changes</span>':'')+(c.publishedVersionId?'<span class="structure-badge">Published version</span>':'')+'<span class="structure-badge '+(c.enabled?'':'off')+'">'+(c.enabled?'Strip enabled':'Strip hidden')+'</span>';document.getElementById('homepageEnabled').checked=!!c.enabled;var mode=document.querySelector('input[name="homepageMode"][value="'+CSS.escape(c.mode||'NEW_ARRIVALS')+'"]');if(mode)mode.checked=true;document.getElementById('homepageHeading').value=c.heading||'';document.getElementById('homepageLimit').value=String(c.productLimit||8);document.getElementById('homepageCollection').innerHTML=homepageCollectionOptions();document.getElementById('homepageCollection').value=c.selectedStorefrontNodeId||'';homepageFeaturedIds=(c.featuredProducts||[]).map(function(p){homepageProductOptions.set(p.productId,p);return p.productId});renderHomepageFeatured();renderHomepageModules();syncHomepageModeUi()}
function syncHomepageModeUi(){var mode=homepageMode();document.getElementById('homepageCollectionWrap').classList.toggle('homepage-hidden',mode!=='SELECTED_COLLECTION');document.getElementById('homepageFeaturedWrap').classList.toggle('homepage-hidden',mode!=='FEATURED_PRODUCTS')}
async function loadHomepage(force){if(homepageLoaded&&!force){renderHomepage();return}try{if(!storefrontNodes.length)await ensureProductStorefrontNodes();var d=await api('/admin/api/homepage-merchandising');homepageConfig=d.config;homepageLoaded=true;renderHomepage()}catch(e){showToast(e.message,true)}}
