ck=function(){saveHomepageDraft(true)};document.getElementById('homepagePreview').onclick=previewHomepage;document.getElementById('homepagePublish').onclick=publishHomepage;document.getElementById('homepageProductSearch').oninput=function(){clearTimeout(homepageSearchTimer);homepageSearchTimer=setTimeout(searchHomepageProducts,180)};
