k=createBrandRange;document.getElementById('refreshOrders').onclick=loadOrders;document.querySelectorAll('[data-order-class]').forEach(function(b){b.onclick=function(){orderDataClass=b.getAttribute('data-order-class')||'BUSINESS';current=null;currentStatus='';loadOrders()}});var resetTestButton=document.getElementById('resetTestOrders');if(resetTestButton)resetTestButton.onclick=resetTestOrders;document.getElementById('orderSearch').oninput=renderOrders;document.getElementById('clearSearch').onclick=function(){document.getElementById('orderSearch').value='';renderOrders()};document.getElementById('refreshProducts').onclick=function(){productsLoaded=false;loadProducts()};document.getElementById('productSearch').oninput=function(){clearTimeout(productTimer);productTimer=setTimeout(function(){productsLoaded=false;loadProducts()},180)};document.getElementById('productSort').onchange=function(){productsLoaded=false;loadProducts()};document.querySelectorAll('[data-product-filter]').forEach(function(b){b.onclick=function(){productFilter=b.getAttribute('data-product-filter')||'all';productsLoaded=false;renderProductFilters();loadProducts()}});document.getElementById('reportDays').onchange=function(){reportDays=Number(this.value)||30;reportsCache=null;loadReports()};document.getElementById('exportReport').onclick=exportCsv;document.getElementById('topDate').onclick=function(){setView('reports')};document.getElementById('logout').onclick=async function(){await fetch('/admin/auth/logout',{method:'POST'});location.href='/admin'};
