export function adminLoginHtml(): string {
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#f4f0e7"><title>The Black Sheep Shop · Admin sign in</title>
<style>:root{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#171713;background:#f4f0e7}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 50% 20%,#fffdf9 0,#f4f0e7 52%,#eee6d7 100%)}.card{width:min(460px,100%);background:rgba(255,253,249,.95);border:1px solid #ded6c8;border-radius:22px;padding:28px;box-shadow:0 18px 50px rgba(40,31,19,.08)}.brand{display:flex;gap:10px;align-items:center;margin-bottom:26px}.mark{width:38px;height:38px;border-radius:13px;background:#171713;color:#fff;display:grid;place-items:center;font-family:Georgia,serif;font-weight:700}.brand-copy{font-family:Georgia,serif;font-size:19px;line-height:1}.eyebrow{color:#756f64;font-size:13px}h1{font-family:Georgia,serif;font-size:38px;line-height:1;margin:4px 0 10px}.muted{color:#756f64;line-height:1.45}.security{border:1px solid #e7dfd2;background:#faf6ed;border-radius:13px;padding:12px;margin:18px 0;font-size:12px;color:#655f56}button,input{font:inherit;width:100%;border-radius:12px;padding:13px}button{border:0;background:#171713;color:#fff;font-weight:800;cursor:pointer;margin-top:10px}.secondary{background:transparent;color:#171713;border:1px solid #d5ccbc}.link{background:transparent;color:#171713;padding:10px;margin-top:4px;text-decoration:underline;text-underline-offset:3px}input{border:1px solid #d5ccbc;background:#fff;margin-top:10px;font-size:17px;outline:none}#code{letter-spacing:5px;font-size:22px;text-align:center}input:focus{border-color:#9e927f;box-shadow:0 0 0 3px rgba(178,161,132,.14)}#verify,#passwordPanel{display:none}.status{min-height:24px;margin-top:12px;font-size:13px}.error{color:#9b1c1c}</style></head>
<body><main class="card"><div class="brand"><div class="mark">BS</div><div class="brand-copy">The Black<br>Sheep Shop</div></div><div class="eyebrow">Private owner dashboard</div><h1>Admin sign in</h1><p class="muted">Sign in with a one-time code sent to the owner email, or use the Admin password.</p><div class="security">Sessions use a secure HTTP-only cookie. Email codes expire after 10 minutes. Password sign-in locks temporarily after repeated failed attempts.</div><div id="codePanel"><button id="send">Send login code</button><button id="usePassword" class="link">Use password</button><div id="verify"><input id="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="000000"><button id="enter">Sign in</button></div></div><div id="passwordPanel"><input id="password" type="password" autocomplete="current-password" placeholder="Admin password"><button id="passwordEnter">Sign in with password</button><button id="useCode" class="link">Use login code instead</button></div><div id="status" class="status" aria-live="polite"></div></main>
<script>var loginStatus=document.getElementById('status'),verify=document.getElementById('verify'),codePanel=document.getElementById('codePanel'),passwordPanel=document.getElementById('passwordPanel');async function post(path,body){var r=await fetch(path,{method:'POST',headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined}),j=await r.json().catch(function(){return {}});if(!r.ok)throw new Error(j&&j.error&&j.error.message||'Request failed');return j}function openAdmin(){loginStatus.textContent='Signed in. Opening Admin…';history.replaceState(null,'',location.hostname==='admin.theblacksheepshop.co.uk'?'/':'/admin'+location.search+'#orders');location.reload()}document.getElementById('usePassword').onclick=function(){codePanel.style.display='none';passwordPanel.style.display='block';loginStatus.textContent='';document.getElementById('password').focus()};document.getElementById('useCode').onclick=function(){passwordPanel.style.display='none';codePanel.style.display='block';loginStatus.textContent=''};document.getElementById('send').onclick=async function(){loginStatus.className='status';loginStatus.textContent='Sending…';try{await post('/admin/auth/request');verify.style.display='block';loginStatus.textContent='Code sent. Check the owner email.';document.getElementById('code').focus()}catch(e){loginStatus.className='status error';loginStatus.textContent=e.message}};document.getElementById('enter').onclick=async function(){var code=document.getElementById('code').value.trim();loginStatus.className='status';loginStatus.textContent='Checking…';try{await post('/admin/auth/verify',{code:code});openAdmin()}catch(e){loginStatus.className='status error';loginStatus.textContent=e.message}};document.getElementById('passwordEnter').onclick=async function(){var password=document.getElementById('password').value;loginStatus.className='status';loginStatus.textContent='Checking…';try{await post('/admin/auth/password',{password:password});openAdmin()}catch(e){loginStatus.className='status error';loginStatus.textContent=e.message}};document.getElementById('code').addEventListener('keydown',function(e){if(e.key==='Enter')document.getElementById('enter').click()});document.getElementById('password').addEventListener('keydown',function(e){if(e.key==='Enter')document.getElementById('passwordEnter').click()});</script></body></html>`;
}
